package com.asmj.marketplace.engagement;
import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.CompoundIndex; import org.springframework.data.mongodb.core.mapping.Document;
@Document("stock_alert_subscriptions") @CompoundIndex(name="stock_alert_user_product_uq",def="{'customerUserId':1,'productId':1}",unique=true)
public class StockAlertSubscription { @Id private String id; private String customerUserId; private String productId; private String productName; private String customerEmail; private boolean notified; private Instant createdAt=Instant.now(); private Instant notifiedAt; public String getId(){return id;} public void setId(String v){id=v;} public String getCustomerUserId(){return customerUserId;} public void setCustomerUserId(String v){customerUserId=v;} public String getProductId(){return productId;} public void setProductId(String v){productId=v;} public String getProductName(){return productName;} public void setProductName(String v){productName=v;} public String getCustomerEmail(){return customerEmail;} public void setCustomerEmail(String v){customerEmail=v;} public boolean isNotified(){return notified;} public void setNotified(boolean v){notified=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getNotifiedAt(){return notifiedAt;} public void setNotifiedAt(Instant v){notifiedAt=v;} }
